struct Original:H8SEmulator{int wh()const{return lastwrite;}void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t time,pending;uint32_t address;uint8_t value;bool write;};
static bool observed(uint32_t a){return a<0x100||(a>=0x8000&&a<0x1c300)||a==0xfffff2||a==0xffffcb||(a>=0xffffe0&&a<=0xffffe8);}
struct RefBus:H8SDevice{Original&c;std::array<Event,16>e{};unsigned n=0;explicit RefBus(Original&x):c(x){}uint8_t read(uint32_t a)override{auto v=c.memory[a];if(observed(a))e[n++]={c.cycles,c.pending_irqs,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(observed(a))e[n++]={c.cycles,c.pending_irqs,a,v,true};c.memory[a]=v;}};
struct NativeBus:kstation::ControllerResourceBus{std::array<Event,16>e{};unsigned n=0;bool mapped(uint32_t a)const override{return a<0x100||(a>=0x8000&&a<0x1c300)||a>=0xfffd00;}uint8_t read(uint32_t a)override{auto v=state_->memory[a];if(observed(a))e[n++]={state_->cycles,state_->pendingIrqs,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(observed(a))e[n++]={state_->cycles,state_->pendingIrqs,a,v,true};state_->memory[a]=v;}};
static uint32_t seed=0xadc6101;static uint32_t rnd(){seed^=seed<<13;seed^=seed>>17;return seed^=seed<<5;}
int main(int argc,char**argv){uint64_t adjacentHistory=0;if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto cpu=std::make_unique<Original>();auto d=std::make_unique<kstation::ControllerDeviceState>();cpu->loadmem(rom.data(),unsigned(rom.size()),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RefBus x(*cpu);NativeBus y;cpu->memmap(&x,0,0x100);cpu->memmap(&x,0x8000,0x14300);cpu->memmap(&x,0xfffd00,0x300);kstation::ControllerInterruptRuntime runtime;if(!runtime.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;d->attachBus(&y);uint64_t phases=0,events=0,shorts=0,mutations=0,quick=0,shortScan=0,longScan=0;for(unsigned n=0;n<3000;++n){runtime.reset();auto put=[&](uint32_t a,uint8_t v){cpu->memory[a]=d->memory[a]=v;};for(uint32_t a=0xc000;a<0xc600;++a)put(a,uint8_t(rnd()));uint8_t remaining=n%5==0?0:n%5==1?1:uint8_t(2+n%7);put(0xc491,remaining);if(!remaining)++longScan;else if(remaining==1)++shortScan;else ++quick;put(0xc490,uint8_t((n%8)*4));auto producer=(uint16_t(cpu->memory[0xc1cc])<<8)|cpu->memory[0xc1cd];put(0xc1d0+producer,uint8_t(rnd()));put(0xc1d1+producer,uint8_t(rnd()));for(unsigned j=0;j<8;++j)put(0xffffe0+j,uint8_t(rnd()));put(0xffffe8,uint8_t(rnd()));put(0xffffcb,uint8_t(rnd()));put(0xfffff2,8);cpu->setSP(0xfffec0);cpu->pc=cpu->makepc(0x3000);cpu->ccr=0;cpu->pending_irqs=d->pendingIrqs=(uint64_t(1)<<60)|(uint64_t(1)<<61);cpu->pending_irqs_high=d->pendingIrqsHigh=0;cpu->interruptMode2=d->interruptMode2=false;cpu->cycles=d->cycles=n%101?rnd():~uint64_t(0)-4;cpu->history(-1,-1);d->lastRead=d->lastWrite=-1;bool entered=false;for(unsigned phase=0;!entered||runtime.active();++phase){if(phase>3000)return 3;auto pc=uint32_t(cpu->getPC());if(n%5==0&&(pc==0x6d2||pc==0x6d4)){auto a=uint32_t(cpu->reg32(2))&0xffffff;put(a,uint8_t(rnd()));++mutations;}x.n=y.n=0;auto before=d->cycles;for(unsigned b=0;b<3;++b){auto r=runtime.advanceBefore(*d,b);if(r.clocks||x.n||y.n||d->cycles!=before)return 4;++shorts;}cpu->step();if(!entered){auto a=runtime.advanceBefore(*d,13);if(!a.entered||a.clocks!=13)return 5;entered=true;auto body=runtime.advanceBefore(*d,6);if(body.clocks!=6)return 6;}else{auto body=runtime.advanceBefore(*d,128);if(!body.clocks||body.blocked!=kstation::ControllerInterruptRuntime::Block::None){std::fprintf(stderr,"blocked n=%u phase=%u pc=%x block=%u\n",n,phase,pc,unsigned(body.blocked));return 7;}}if(cpu->cycles!=d->cycles||cpu->pending_irqs!=d->pendingIrqs||x.n!=y.n){std::fprintf(stderr,"phase n=%u phase=%u pc=%x clocks=%llu/%llu io=%u/%u\n",n,phase,pc,(unsigned long long)cpu->cycles,(unsigned long long)d->cycles,x.n,y.n);return 8;}for(unsigned j=0;j<x.n;++j){auto a=x.e[j],b=y.e[j];if(a.time!=b.time||a.pending!=b.pending||a.address!=b.address||a.value!=b.value||a.write!=b.write){std::fprintf(stderr,"event n=%u phase=%u pc=%x idx=%u addr=%x/%x val=%x/%x time=%llu/%llu\n",n,phase,pc,j,a.address,b.address,a.value,b.value,(unsigned long long)a.time,(unsigned long long)b.time);return 9;}}events+=x.n;++phases;if(phase==0&&(n&1)){cpu->pending_irqs|=uint64_t(1)<<38;d->pendingIrqs|=uint64_t(1)<<38;}}for(uint32_t a=0xc000;a<0xc600;++a)if(cpu->memory[a]!=d->memory[a]){std::fprintf(stderr,"memory n=%u address=%x\n",n,a);return 10;}{auto old=cpu->wh();if(old>=0&&!(old&1))++adjacentHistory;uint32_t target=old>=0&&!(old&1)?uint32_t(old+1):0xfffe73;x.n=y.n=0;cpu->write8(0x5a,int(target));d->write8(target,0x5a);if(cpu->cycles!=d->cycles||x.n!=y.n)return 21;for(unsigned z=0;z<x.n;++z){auto u=x.e[z],v=y.e[z];if(u.time!=v.time||u.address!=v.address||u.value!=v.value||u.write!=v.write)return 22;}}}std::printf("PASS CPU-free ADC IRQ: 3000 calls (%llu quick, %llu short, %llu full), %llu H8 phases, %llu ordered events, %llu short budgets, %llu live mutations\n",(unsigned long long)quick,(unsigned long long)shortScan,(unsigned long long)longScan,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)mutations);}
